const assert = require('assert');

describe('Mailchimp Customer Sync Boundary & Privacy Policy', () => {
  it('states that marketing sync must be opt-in and disabled by default', () => {
    const config = {
      integrations: {
        mailchimp: {
          enabled: false,
          optInRequired: true
        }
      }
    };
    assert.strictEqual(config.integrations.mailchimp.enabled, false, 'Mailchimp sync must be disabled by default');
    assert.strictEqual(config.integrations.mailchimp.optInRequired, true, 'Marketing sync must be opt-in');
  });

  it('defines allowed customer fields and explicit consent requirements', () => {
    const fieldPolicy = {
      email: { exportable: true, requiresConsent: true },
      firstName: { exportable: true, requiresConsent: false },
      lastName: { exportable: true, requiresConsent: false },
      phone: { exportable: false, requiresConsent: true, reason: 'PII / sensitive' },
      purchaseHistory: { exportable: false, requiresConsent: true, reason: 'Financial / sensitive' }
    };

    assert.strictEqual(fieldPolicy.email.requiresConsent, true);
    assert.strictEqual(fieldPolicy.phone.exportable, false);
  });

  it('provides a synthetic customer sync fixture with official API doc references and consent metadata', () => {
    const fixture = {
      docReferences: {
        contactsAudiences: 'https://mailchimp.com/developer/marketing/api/contacts/',
        consentFields: 'https://mailchimp.com/developer/marketing/docs/merge-fields/',
        tags: 'https://mailchimp.com/developer/marketing/api/tags/',
        unsubscribeHandling: 'https://mailchimp.com/developer/marketing/api/lists/update-list-member/'
      },
      syntheticCustomer: {
        email_address: 'synthetic.customer@example.com',
        status: 'subscribed',
        merge_fields: {
          FNAME: 'Jane',
          LNAME: 'Doe'
        },
        tags: ['posnic-retail-customer', 'opt-in-verified'],
        marketing_consent: {
          opt_in: true,
          timestamp: '2023-10-01T00:00:00Z'
        }
      }
    };

    assert.ok(fixture.docReferences.contactsAudiences);
    assert.ok(fixture.syntheticCustomer.email_address);
    assert.strictEqual(fixture.syntheticCustomer.marketing_consent.opt_in, true);
  });
});
```

