/* 
--------------------------------
    : Custom - General css :
--------------------------------
*/
html {
  position: relative;
  min-height: 100%;
}

body {
  font-family: "Mukta Vaani", sans-serif;
  margin: 0;
  background: #f2f3f7;
  font-size: 16px;
  font-weight: 300;
  color: #8A98AC;
  line-height: 1.5;
}

.h1,
.h2,
.h3,
.h4,
.h5,
.h6,
h1,
h2,
h3,
h4,
h5,
h6 {
  font-weight: 500;
  color: #141d46;
}

h1 {
  font-size: 38px;
}

h2 {
  font-size: 30px;
}

h3 {
  font-size: 26px;
}

h4 {
  font-size: 22px;
}

h5 {
  font-size: 18px;
}

h6 {
  font-size: 16px;
}

b {
  font-weight: 700;
}

strong {
  font-weight: 700;
}

p {
  line-height: 1.3;
  margin-bottom: 10px;
}

label {
  vertical-align: middle;
}

* {
  outline: none !important;
}

a {
  color: var(--theme-primary-color, #506fe4);
}

a:hover {
  color: #3a5de1;
  outline: 0;
  text-decoration: none;
}

a:active {
  color: #3a5de1;
  outline: 0;
  text-decoration: none;
}

a:focus {
  color: #3a5de1;
  outline: 0;
  text-decoration: none;
}

code {
  color: var(--theme-primary-color, #506fe4);
}

.logobar {
  padding: 15px 0;
  margin-bottom: 0;
  text-align: center;
  border-bottom: 1px solid rgba(0, 0, 0, 0.03);
}

.logobar .logo img {
  width: 100px;
  height: 40px;
}

.badge_font {
  font-size: 10px !important;
}

.leftbar {
  width: 256px;
  height: 100%;
  position: fixed;
  background: #ffffff;
  z-index: 99;
  /* Only animate the toggle-collapse (width/left/transform) - NOT height.
     'transition: all' was animating the height on every window resize, so the
     bar appeared to render slowly top-to-bottom while dragging. */
  transition: width 0.3s ease, left 0.3s ease, transform 0.3s ease;
}

.rightbar {
  margin-left: 256px;
  overflow: hidden;
  min-height: 500px;
  transition: margin-left 0.3s ease;
}

.contentbar {
  padding: 30px;
  margin-bottom: 30px;
}

.footerbar {
  position: absolute;
  bottom: 0;
  right: 0;
  left: 256px;
  padding: 20px 30px;
  text-align: center;
  background-color: #ffffff;
  background-color: #ffffff;
}

.toggle-menu .footerbar {
  left: 0;
}

.slimScrollBar {
  z-index: 0 !important;
}

.navigationbar {
  height: calc(100vh - 0px);
  overflow: auto;
  -webkit-transition: 0.5s;
  transition: 0.5s;
}

::-webkit-scrollbar {
  width: 0;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: transparent;
}

::-webkit-scrollbar-thumb:hover {
  background: transparent;
}

.vertical-menu-detail {
  border-right: 1px solid rgba(0, 0, 0, 0.03);
  display: -webkit-box;
  display: -webkit-flex;
  display: -moz-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-flex: 1;
  -webkit-flex-grow: 1;
  -moz-box-flex: 1;
  -ms-flex-positive: 1;
  flex-grow: 1;
  -webkit-box-orient: vertical;
  -webkit-box-direction: normal;
  -webkit-flex-direction: column;
  -moz-box-orient: vertical;
  -moz-box-direction: normal;
  -ms-flex-direction: column;
  flex-direction: column;
}

.vertical-menu-detail .logobar {
  margin-bottom: 5px;
}

.vertical-menu-icon {
  height: 100%;
  width: 60px;
  float: left;
  background-color: var(--theme-primary-color, #506fe4);
  display: -webkit-box;
  display: -webkit-flex;
  display: -moz-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-direction: normal;
  -webkit-flex-direction: column;
  -moz-box-orient: vertical;
  -moz-box-direction: normal;
  -ms-flex-direction: column;
  flex-direction: column;
  -webkit-box-pack: justify;
  -webkit-justify-content: space-between;
  -moz-box-pack: justify;
  -ms-flex-pack: justify;
  justify-content: space-between;
  padding: 0;
  overflow: hidden;
}

.vertical-menu-icon .nav-pills .nav-link {
  padding: 7px 5px;
  margin: 10px;
  text-align: center;
  border-radius: 3px;
}

.vertical-menu-icon .nav-pills .nav-link img {
  width: 25px;
}

.vertical-menu-icon .nav-pills .nav-link.active {
  background-color: rgba(0, 0, 0, 0.3);
}

.vertical-menu-icon .nav-pills .logobar {
  margin-bottom: 200px;
}

.menu-title {
  margin-bottom: 10px;
  padding: 10px 15px;
  font-size: 18px;
  color: #141d46;
  border-bottom: 1px solid rgba(0, 0, 0, 0.03);
}

